<script>
    $(document).ready(function () {
        $(""#OrderIds"").change(loadproducts);
    });
    function loadproducts() {
        var orderid = $(""#OrderIds"").val();
        if (orderid != """" && orderid != ""-1"") {
            $.ajax({
                type: 'Get',
                url: window.location.origin + '/BasketItem/GetBookingHistory?orderid=' + orderid,
                contentType: 'application/x-www-form-urlencoded; charset=UTF-8',
                success: function (data) {
                    if ($.trim(data) != '') {
                        $('#bookHistory').empty();
                        $('#bookHistory').append(data);
                    }
                    else {
                        $('#bookHistory').empty();
                    }
                },
                error: function (error) {
                    alert(""Error: "" + error);
                }
            });
        }
    }
</script>");
